# Procurar o primeiro número, entre 1 e 20, que seja divisível por 7
for i in range(1, 21):
    if i % 7 == 0:
        print("Achei:", i)
        break  # para o laço assim que encontra, não precisa continuar
# saida: Achei: 7

# Mostrar os números de 1 a 10, mas pulando os múltiplos de 3
for i in range(1, 11):
    if i % 3 == 0:
        continue  # pula esta volta, vai direto para a próxima
    print(i)
# saida: 1 2 4 5 7 8 10   (pulou o 3, o 6 e o 9)

